<?php require "../config.php";if(!isset($_SESSION["user_id"])){header("Location: login.php");exit;}$msg="";$deps=$pdo->query("SELECT * FROM departments")->fetchAll(PDO::FETCH_ASSOC);if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$pdo->prepare("INSERT INTO emergency_reports(user_id,department_id,type,location,description) VALUES(?,?,?,?,?)");$s->execute([$_SESSION["user_id"],$_POST["department_id"],$_POST["type"],$_POST["location"],$_POST["description"]]);$msg="Emergency report submitted successfully.";}?><!doctype html><html><head><title>Report Emergency</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form panel"><h2>Report Emergency</h2><?php if($msg):?><div class="msg"><?=$msg?></div><?php endif;?><form method="post"><label>Emergency Type</label><select name="type" required><option>Medical Emergency</option><option>Fire</option><option>Police / Crime</option><option>Road Accident</option><option>Flood</option><option>Natural Disaster</option><option>Other</option></select><label>Department</label><select name="department_id" required><?php foreach($deps as $d):?><option value="<?=$d["id"]?>"><?=$d["name"]?> - <?=$d["contact"]?></option><?php endforeach;?></select><input name="location" placeholder="Emergency location" required><textarea name="description" rows="5" placeholder="Describe the emergency" required></textarea><button class="btn">Submit Emergency Report</button></form><p><a href="dashboard.php">Dashboard</a></p></div></body></html>